import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetDisplayObjective{DisplaySlot: "sidebar", ObjectiveName: "objective", DisplayName: "Scores",
#   CriteriaName: "dummy", SortOrder: packet.ScoreboardSortOrderDescending}
SIDEBAR = bytes.fromhex("0773696465626172096f626a6563746976650653636f7265730564756d6d7902")

# generated by gophertunnel b8bd735:
# &packet.SetDisplayObjective{}
ASCENDING = bytes.fromhex("0000000000")

# generated by gophertunnel b8bd735:
# &packet.SetDisplayObjective{SortOrder: packet.ScoreboardSortOrderDescending}
DESCENDING = bytes.fromhex("0000000002")

# generated by gophertunnel b8bd735:
# &packet.SetDisplayObjective{DisplayName: strings.Repeat("x", 200)}
LONG_DISPLAY_NAME = bytes.fromhex("0000c801") + bytes.fromhex("78") * 200 + bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v2225.SetDisplayObjectivePacket(
            display_slot_name="sidebar",
            objective_name="objective",
            objective_display_name="Scores",
            criteria_name="dummy",
            sort_order=v2225.ObjectiveSortOrder.DESCENDING,
        ),
        SIDEBAR,
        id="sidebar",
    ),
    pytest.param(
        v2225.SetDisplayObjectivePacket(sort_order=v2225.ObjectiveSortOrder.ASCENDING),
        ASCENDING,
        id="ascending-is-a-zigzag-varint",
    ),
    pytest.param(
        v2225.SetDisplayObjectivePacket(sort_order=v2225.ObjectiveSortOrder.DESCENDING),
        DESCENDING,
        id="descending-is-a-zigzag-varint",
    ),
    pytest.param(
        v2225.SetDisplayObjectivePacket(objective_display_name="x" * 200),
        LONG_DISPLAY_NAME,
        id="display-name-over-127-bytes-takes-a-two-byte-length",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_set_display_objective_is_packet_107(version):
    assert version.packets[107] is version.SetDisplayObjectivePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_display_objective_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_display_objective_decodes_from_its_golden(packet, golden):
    assert v2225.SetDisplayObjectivePacket.from_bytes(golden) == packet
